// Résolution du lien du document depuis la page d'index.
//
// Le nom du fichier change à chaque parution (histo_elec-meca_260707_f.pdf pour
// juillet 2026) : la liaison déclare la page STABLE et le motif du lien. Même
// principe que le connecteur de classeur indexé, et même raison — reconstruire
// l'URL par calcul de date supposerait de connaître la convention de nommage du
// producteur, qui n'est pas documentée et a déjà changé.
//
// L'URL résolue est consignée : elle fait partie de la trace d'audit du run.
const page = $json.data ?? $json.body ?? '';
const m = /(\/scripts\/getstat\.php\?file=histo_elec-meca_(\d{6})_f\.pdf)/.exec(String(page));
if (!m) throw new Error("lien histo_elec-meca introuvable sur la page d'index — structure de la page modifiée, à instruire");
return [{ json: {
  url_document: 'https://www.fhs.swiss' + m[1].replace(/&amp;/g, '&'),
  millesime: m[2]
} }];

// ANALYSE EN FLUX DE JETONS, et non en colonnes.
//
// POURQUOI. Le nœud de lecture PDF ne préserve pas l'alignement visuel du
// document : les six valeurs d'un mois se retrouvent réparties sur plusieurs
// lignes de sortie. Vérifié en réponse réelle le 25.08.2026 — un découpage par
// lignes ne rend que deux ou trois valeurs sur six. Mais les nombres restent
// dans le BON ORDRE. On lit donc le document comme une suite de jetons : dès
// qu'un libellé de mois apparaît, les six nombres qui suivent sont ses colonnes.
//
// C'est ce qui permet de se passer d'un outil externe d'extraction et de tout
// tenir dans l'orchestrateur.
const runId = $('Ouvrir le run').first().json.run_id;
const url = $('Résoudre le lien du document').first().json.url_document;
const t = ($json.text || '').replace(/[\r\n]+/g, ' ');

// Le nœud rend un texte mal décodé (« fÃ©v » pour « fév ») : les deux graphies
// sont acceptées plutôt que de corriger l'encodage en amont, ce qui serait
// fragile si le producteur changeait de jeu de caractères.
const MOIS = { jan:'01', 'fÃ©v':'02', 'fév':'02', fev:'02', mar:'03', avr:'04',
               mai:'05', jun:'06', jui:'07', aou:'08', 'aoÃ»':'08', 'aoû':'08',
               sep:'09', oct:'10', nov:'11', 'dÃ©c':'12', 'déc':'12', dec:'12' };

// Ordre des colonnes du tableau, vérifié par le contrôle de cohérence plus bas.
const COLONNES = ['total_pieces','total_chf','elec_pieces','elec_chf','meca_pieces','meca_chf'];
// Ce que chaque indicateur prélève.
const PLAN = { H7: 'total_chf', H8: 'meca_chf', H9: 'meca_pieces' };

const jetons = t.split(/\s+/).filter(Boolean);
const nombre = s => {
  const n = parseFloat(String(s).replace(/['’]/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};

const lignes = {};
const incidents = [];
for (let i = 0; i < jetons.length; i++) {
  const mois = MOIS[jetons[i]];
  if (!mois) continue;
  const an = jetons[i + 1];
  if (!/^\d{2}$/.test(an || '')) continue;
  const vals = [];
  let j = i + 2;
  while (j < jetons.length && vals.length < COLONNES.length) {
    const v = nombre(jetons[j]);
    if (v === null) break;
    vals.push(v); j++;
  }
  if (vals.length === COLONNES.length) {
    lignes[`20${an}-${mois}`] = Object.fromEntries(COLONNES.map((c, k) => [c, vals[k]]));
  } else {
    incidents.push(`${jetons[i]} ${an} : ${vals.length} colonne(s) lue(s) sur ${COLONNES.length}`);
  }
  i = j - 1;
}

const cles = Object.keys(lignes).sort();
if (cles.length === 0) throw new Error('aucune ligne mensuelle extraite — structure du document modifiée, à instruire');

// CONTRÔLE DE COHÉRENCE AVANT ÉCRITURE, et non après. L'ordre des colonnes est
// une HYPOTHÈSE sur le document : on la teste. Électroniques + mécaniques
// doivent reconstituer le total des montres-bracelets. Un écart important
// signale que les colonnes ont bougé — et l'écriture est alors refusée.
let pire = 0, pireMois = null, somme = 0, n = 0;
for (const k of cles) {
  const v = lignes[k];
  if (!(v.total_chf > 0)) continue;
  const e = Math.abs((v.elec_chf + v.meca_chf) - v.total_chf) / v.total_chf * 100;
  if (e > pire) { pire = e; pireMois = k; }
  somme += e; n++;
}
const moyen = n ? somme / n : 0;
const ok = pire < 8;
const controle = `écart élec+méca contre total : moyen ${moyen.toFixed(2)} %, maximum ${pire.toFixed(2)} %`
  + (pireMois ? ` (${pireMois})` : '') + ` — ${ok ? 'ordre des colonnes confirmé' : 'ORDRE DES COLONNES SUSPECT'}`;
if (!ok) throw new Error('écriture refusée — ' + controle);

const sorties = [];
for (const k of cles) {
  for (const [code, colonne] of Object.entries(PLAN)) {
    const v = lignes[k][colonne];
    if (v === undefined || v === null) continue;
    sorties.push({ json: { indicator_id: code, run_id: runId, period: k,
                           geo: 'CH', value: v, raw_ref: url,
                           _bilan: { mois: cles.length, premier: cles[0], dernier: cles[cles.length-1],
                                     controle, incidents, indicateurs: Object.keys(PLAN) } } });
  }
}
return sorties;

